<script setup lang="ts">
import { computed, onUnmounted, ref, watch } from 'vue'
import { api, formatShanghai, sessionToken } from '../api'
import type { Identity } from '../api'
import InvoiceActions from '../components/InvoiceActions.vue'
import WorkspaceStatistics from '../components/WorkspaceStatistics.vue'
type Row=Record<string,unknown>
type Data={today:string;stats:{today:string;guestToday?:string;arrived:string;unbilled:string;followups:string};visits:Row[];followups:Row[];patients:Row[];projects:Row[];dentists:Row[];clinics:Row[]}
const props=defineProps<{identity:Identity;clinicId:string;mode:string}>()
const emit=defineEmits<{navigate:[page:string]}>()
const data=ref<Data|null>(null),error=ref(''),loading=ref(false),message=ref(''),details=ref<Row|null>(null)
let generation=0,disposed=false
const titles:Record<string,[string,string,string]>={dashboard:['口腔诊所工作台','从预约到复诊，让每一次看牙都有清晰记录。','DENTAL CARE WORKSPACE'],queue:['患者队列','核对就诊安排，登记患者实际到诊。','PATIENT QUEUE'],billing:['就诊结算','只依据牙医已确认的实际治疗办理同次结算。','VISIT BILLING'],patients:['患者管理','查看获权门店就诊患者的摘要，办理时核对本人档案。','PATIENT PROFILES'],projects:['诊疗项目','标准单位价格供预约前参考，实际费用以本次治疗为准。','DENTAL SERVICES'],dentists:['牙医管理','牙医专业信息与门店出诊资料。','DENTIST MANAGEMENT'],clinics:['门店信息','查看连锁门店和联系方式。','CLINIC LOCATIONS']}
const title=computed(()=>titles[props.mode]||titles.dashboard!)
const todayVisits=computed(()=>data.value?.visits.filter(o=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'}).format(new Date(String(o.scheduled_start)))===data.value?.today)||[])
const visits=computed(()=>props.mode==='billing'?data.value?.visits.filter(o=>o.treatment_status==='已完成')||[]:data.value?.visits.filter(o=>!['患者取消','诊所撤销','误录作废','已改约'].includes(String(o.appointment_status)))||[])
const pendingPlans=computed(()=>data.value?.followups.filter(p=>p.status==='待复诊')||[])
const statusStats=computed(()=>{const rows=data.value?.visits||[];const map=new Map<string,number>();for(const r of rows){const k=String(r.appointment_status||'未标注');map.set(k,(map.get(k)||0)+1)}return [...map.entries()].map(([name,count])=>({name,count})).sort((a,b)=>b.count-a.count).slice(0,5)})
const statusMax=computed(()=>Math.max(1,...statusStats.value.map(d=>d.count)))
const channels=computed(()=>{const rows=data.value?.visits||[];const map=new Map<string,number>();for(const r of rows){const k=String(r.booking_channel||'未标注');map.set(k,(map.get(k)||0)+1)}const total=rows.length||1;return [...map.entries()].map(([name,count])=>({name,count,pct:Math.round(count/total*100)})).sort((a,b)=>b.count-a.count)})
const canFront=computed(()=>props.identity.grants.some(g=>g.role_code==='前台'))
const canReadStatistics=computed(()=>props.identity.grants.some(g=>
  ['前台','运营人员／店长','总部管理'].includes(g.role_code) &&
  (g.scope_kind==='连锁' || props.clinicId==='0' || String(g.clinic_id)===props.clinicId)))
watch(()=>[props.identity,props.clinicId],()=>void load(),{immediate:true})
onUnmounted(()=>{disposed=true;generation++})
async function load(){const seq=++generation,token=sessionToken();loading.value=true;error.value='';try{const result=await api<Data>(`/staff/workspace?clinicId=${encodeURIComponent(props.clinicId)}`);if(!disposed&&seq===generation&&token===sessionToken())data.value=result}catch(e){if(!disposed&&seq===generation)error.value=e instanceof Error?e.message:'读取失败'}finally{if(!disposed&&seq===generation)loading.value=false}}
function status(o:Row){return o.treatment_status==='已完成'?'已完成':String(o.appointment_status)}
function shortClinic(name:unknown){return String(name||'').replace('和安口腔·','').replace('（课程演示）','')}
async function arrive(o:Row){error.value='';try{await api(`/staff/appointments/${o.appointment_id}/arrival`,{method:'POST'});message.value='已登记实际到诊，后续由接诊牙医确认治疗。';await load()}catch(e){error.value=e instanceof Error?e.message:'登记失败'}}
async function detail(o:Row){try{const result=await api<Row>(`/staff/appointments/${o.appointment_id}`);details.value={...o,...result};}catch(e){error.value=e instanceof Error?e.message:'详情读取失败'}}
async function invoice(o:Row){try{const r=await api<{appointment:Row;invoice:Row|null}>(`/staff/appointments/${o.appointment_id}`);if(r.invoice?.invoice_id){details.value={...o,bill:await api<Row>(`/staff/invoices/${r.invoice.invoice_id}`)};return}details.value={...o,issue:true}}catch(e){error.value=e instanceof Error?e.message:'结算读取失败'}}
async function issue(){if(!details.value)return;try{const result=await api<{invoice:Row}>(`/staff/appointments/${details.value.appointment_id}/invoice-draft`,{method:'POST'});details.value={...details.value,bill:result.invoice,issue:false};message.value='结算草稿已生成，请核对后发出。';await load()}catch(e){error.value=e instanceof Error?e.message:'开单失败'}}
async function patient(p:Row){try{const rows=await api<Row[]>(`/staff/patients?clinicId=${props.clinicId==='0'?data.value?.visits.find(o=>o.patient_id===p.patient_id)?.clinic_id||'1':props.clinicId}&q=${encodeURIComponent(String(p.patient_no))}`);details.value={profile:rows[0]}}catch(e){error.value=e instanceof Error?e.message:'档案读取失败'}}
</script>
<template>
 <div class="pagehead" :class="{'dashboard-banner':mode==='dashboard'}"><div class="pagehead-copy"><div class="eyebrow">{{title?.[2]}}</div><h1>{{title?.[0]}}</h1><p class="sub">{{title?.[1]}}</p></div><div class="pagehead-actions"><button v-if="mode==='dashboard'" @click="emit('navigate','consultation')">进入接诊工作台</button><button v-else class="secondary" :disabled="loading" @click="load">刷新数据</button></div></div>
 <p v-if="error" class="care-warning" role="alert">{{error}}</p><p v-if="message" class="tip">{{message}}</p><p v-if="loading&&!data" class="muted">正在读取门店业务数据…</p>
 <template v-if="data">
  <div v-if="mode==='dashboard'" class="stats">
   <div class="stat"><span class="stat-ico" style="background:#e9f1ff;color:#2f6bff"><svg viewBox="0 0 24 24"><rect x="3" y="5" width="18" height="16" rx="2.5"/><path d="M8 3v4M16 3v4M3 10.5h18"/></svg></span><label>今日预约</label><div class="number">{{data.stats.today}}<small>人</small></div><div class="statfooter">含自助、电话与柜台预约</div></div>
   <div class="stat"><span class="stat-ico" style="background:#e7f8f0;color:#12b886"><svg viewBox="0 0 24 24"><path d="M20 6 9 17l-5-5"/></svg></span><label>已到诊待治疗</label><div class="number">{{data.stats.arrived}}<small>人</small></div><div class="statfooter">到诊与诊疗完成分别登记</div></div>
   <div class="stat"><span class="stat-ico" style="background:#fdf3e2;color:#f5a524"><svg viewBox="0 0 24 24"><path d="M14 2.5H7A2.5 2.5 0 0 0 4.5 5v14A2.5 2.5 0 0 0 7 21.5h10a2.5 2.5 0 0 0 2.5-2.5V8z"/><path d="M14 2.5V8h5.5"/></svg></span><label>待补开结算</label><div class="number">{{data.stats.unbilled}}<small>单</small></div><div class="statfooter">只依据已确认实际治疗开单</div></div>
   <div class="stat"><span class="stat-ico" style="background:#efeafe;color:#7c6bf5"><svg viewBox="0 0 24 24"><path d="M20.5 12a8.5 8.5 0 1 1-2.6-6.1"/><path d="M20.5 3.5V9H15"/><path d="M12 8v4.5l3 1.8"/></svg></span><label>待复诊计划</label><div class="number">{{data.stats.followups}}<small>项</small></div><div class="statfooter">关联预约后仍须实际完成</div></div>
  </div>
  <div v-if="mode==='dashboard'" class="dashboard-grid">
   <section class="panel"><div class="paneltitle"><div><h2>预约状态分布</h2><div class="sub">当前门店全部预约记录 · 共 {{data.visits.length}} 条</div></div><button class="textbtn" @click="load">刷新</button></div><div class="bars"><div v-for="d in statusStats" :key="d.name" class="bar"><span class="bar-v">{{d.count}}</span><i :style="{height: Math.max(6, Math.round(d.count/statusMax*100)) + '%'}"></i><span>{{d.name}}</span></div></div><div class="legend"><span><i style="background:#2f6bff"></i>按预约状态统计</span></div></section>
   <section class="panel"><div class="paneltitle"><div><h2>待复诊提醒</h2><div class="sub">{{pendingPlans.length}} 项待跟进</div></div><button class="textbtn" @click="emit('navigate','followups')">查看计划 →</button></div><div class="tl"><div v-for="p in pendingPlans.slice(0,5)" :key="String(p.followup_plan_id)" class="it"><span class="tm">复诊</span><span class="bd"></span><div class="tx"><b>{{p.patient_name}} · {{p.dentist_name}}</b><span>建议 {{p.suggested_date}} · {{shortClinic(p.clinic_name)}}</span></div></div><p v-if="!pendingPlans.length" class="empty">暂无待复诊计划</p></div></section>
  </div>
  <div v-if="mode==='dashboard'" class="care-columns">
   <section class="panel"><div class="paneltitle"><div><h2>今日接诊安排</h2><div class="sub">按预约时间排序</div></div><button class="textbtn" @click="emit('navigate','queue')">全部接诊 →</button></div><div class="tablewrap"><table><thead><tr><th>患者</th><th>牙医 / 门店</th><th>预约时间</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="o in todayVisits" :key="String(o.appointment_id)"><td>{{o.patient_name}}<small class="cell-sub">{{o.booking_channel}}</small></td><td>{{o.dentist_name}}<small class="cell-sub">{{shortClinic(o.clinic_name)}}</small></td><td>{{formatShanghai(o.scheduled_start)}}</td><td><span class="badge">{{status(o)}}</span></td><td><button v-if="canFront" class="textbtn" @click="detail(o)">详情</button><button data-readonly-write v-if="canFront&&['待到诊','待核实'].includes(String(o.appointment_status))" class="textbtn" @click="arrive(o)">到诊登记</button></td></tr><tr v-if="!todayVisits.length"><td colspan="5" class="empty">今日暂无接诊安排</td></tr></tbody></table></div></section>
   <section class="panel"><div class="paneltitle"><div><h2>预约渠道</h2><div class="sub">当前门店预约来源</div></div></div><div class="chlist"><div v-for="c in channels" :key="c.name" class="chrow"><span class="chname">{{c.name}}</span><span class="chbar"><i :style="{width:c.pct+'%'}"></i></span><b>{{c.pct}}%</b></div><p v-if="!channels.length" class="empty">暂无预约数据</p></div></section>
  </div>
  <section v-else-if="['queue','billing'].includes(mode)" class="panel"><div class="tablewrap"><table><thead><tr><th>患者</th><th>牙医 / 门店</th><th>就诊时间</th><th>预约状态</th><th>治疗阶段</th><th>操作</th></tr></thead><tbody><tr v-for="o in visits" :key="String(o.appointment_id)"><td>{{o.patient_name}}</td><td>{{o.dentist_name}}<small class="cell-sub">{{shortClinic(o.clinic_name)}}</small></td><td>{{formatShanghai(o.scheduled_start)}}</td><td><span class="badge">{{o.appointment_status}}</span></td><td>{{o.treatment_status}}</td><td><button v-if="canFront&&mode==='billing'" class="textbtn" @click="invoice(o)">查看 / 办理结算</button><template v-else-if="canFront"><button class="textbtn" @click="detail(o)">详情</button><button data-readonly-write v-if="['待到诊','待核实'].includes(String(o.appointment_status))" class="textbtn" @click="arrive(o)">到诊登记</button></template></td></tr><tr v-if="!visits.length"><td colspan="6" class="empty">暂无符合条件的就诊记录</td></tr></tbody></table></div></section>
  <section v-else-if="mode==='patients'" class="panel"><div class="paneltitle"><h2>门店就诊患者</h2><button class="textbtn" @click="emit('navigate','appointments')">建档 / 电话代约 ↗</button></div><div class="tablewrap"><table><thead><tr><th>患者编号</th><th>姓名</th><th>过敏询问状态</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="p in data.patients" :key="String(p.patient_id)"><td>{{p.patient_no}}</td><td>{{p.name}}</td><td>{{p.allergy_declaration}}</td><td><span class="badge">{{p.active?'正常':'停用'}}</span></td><td><button class="textbtn" @click="patient(p)">查看档案</button></td></tr></tbody></table></div></section>
  <section v-else-if="mode==='projects'" class="panel"><div class="tablewrap"><table><thead><tr><th>项目代码</th><th>诊疗项目</th><th>标准计量单位</th><th>标准单位参考价</th></tr></thead><tbody><tr v-for="p in data.projects" :key="String(p.treatment_type_id)"><td>{{p.treatment_code}}</td><td>{{p.name}}</td><td>{{p.unit_name}}</td><td>¥{{p.standard_unit_price}}</td></tr></tbody></table></div><p class="sub">预约前参考价格不直接产生费用，结算以实际确认的项目、单位数和当次价格为准。</p></section>
  <div v-else-if="mode==='clinics'" class="cards"><section v-for="c in data.clinics" :key="String(c.clinic_id)" class="panel"><h3>{{c.name}}</h3><p class="sub">{{c.postal_address}}<br>{{c.phone}}</p></section></div>
  <WorkspaceStatistics v-if="mode==='dashboard' && canReadStatistics" :clinic-id="clinicId" :today="data.today" />
  <p v-if="mode==='dashboard' && canReadStatistics && data.stats.guestToday" class="sub">另有 {{ data.stats.guestToday }} 笔今日访客预约待到诊。可在预约管理核对。</p>
 </template>
 <dialog :open="!!details" class="approved-dialog"><template v-if="details"><div class="modalheader"><h2>{{details.profile?'患者档案':details.bill||details.issue?'就诊结算':'预约详情'}}</h2><button class="close" @click="details=null">×</button></div><div class="modalbody"><template v-if="details.profile"><div v-for="[key,label] in [['patient_no','患者编号'],['name','姓名'],['birth_date','出生日期'],['phone','联系电话'],['billing_address','账单地址'],['emergency_name','紧急联系人'],['allergy_declaration','过敏申报']]" :key="key" class="care-info"><span>{{label}}</span><b>{{(details.profile as Row)[key]}}</b></div></template><template v-else><div class="care-info"><span>患者 / 牙医</span><b>{{details.patient_name}} · {{details.dentist_name}}</b></div><div class="care-info"><span>预约时间</span><b>{{formatShanghai(details.scheduled_start)}}</b></div><template v-if="details.bill"><div v-for="line in ((details.bill as Row).lines as Row[]||[])" :key="String(line.invoice_line_id)" class="care-line"><div>{{line.name_snapshot}}<small>{{line.units_snapshot}} {{line.unit_snapshot}} × ¥{{line.unit_price_snapshot}}</small></div><b>¥{{line.subtotal}}</b></div><div class="care-info"><span>结算合计</span><b>¥{{(details.bill as Row).total_amount}}</b></div><InvoiceActions :invoice="details.bill as Row" :read-only="identity.readOnly" @updated="details={...details,bill:$event}; load()" /></template><p v-else-if="details.issue" class="care-warning">本次治疗已完成。确认后，服务器将按已确认的实际项目、价量生成同次唯一结算。</p><div v-else class="care-info"><span>预约 / 治疗状态</span><b>{{details.appointment_status}} / {{details.treatment_status}}</b></div></template></div><div class="modalfooter"><button class="secondary" @click="details=null">关闭</button><button data-readonly-write v-if="details.issue" @click="issue">生成结算草稿</button></div></template></dialog>
</template>
